      "sec-howto": {
        "h2": "सेकेंट अनुपात कैलकुलेटर का उपयोग कैसे करें",
        "blocks": [
          {
            "kind": "p",
            "text": "ऊपर दिया कैलकुलेटर दो इनपुट लेता है, कर्ण [[c]] और संलग्न भुजा [[b]], और [[\\sec(A)]] लौटाता है। इन चरणों का क्रम से पालन करें।"
          }
        ],
        "steps": [
          "<strong>संदर्भ कोण [[A]] पहचानें।</strong> अनुपात में हर भुजा लेबल इस कोण के सापेक्ष परिभाषित है, इसलिए भुजाओं की लंबाइयों को छूने से पहले इसे चुनें।",
          "<strong>कर्ण [[c]] खोजें।</strong> यह समकोण के सामने है और त्रिभुज की सबसे लंबी भुजा है; आरेखों में यह ढलान वाली भुजा होती है।",
          "<strong>संलग्न भुजा [[b]] खोजें।</strong> यह कोण [[A]] को छूती है और कर्ण नहीं है; यह दो लंबवत पादों में से एक है।",
          "<strong>दोनों भुजाओं की लंबाइयाँ प्राप्त करें या मापें।</strong> एक ही यंत्र और एक ही इकाई से मापें, या आगे बढ़ने से पहले एक माप को रूपांतरित करें।",
          "<strong>पहले इनपुट फ़ील्ड में कर्ण दर्ज करें।</strong> यह भिन्न का अंश है, इसलिए यहाँ गलती पूरे उत्तर को बदल देगी।",
          "<strong>दूसरे इनपुट फ़ील्ड में संलग्न भुजा दर्ज करें।</strong> यह हर है; यह कोण [[A]] के बगल वाली भुजा होनी चाहिए, उसके सामने वाली नहीं।",
          "<strong>उपलब्ध इकाई चयनकर्ताओं से संगत मापन इकाइयाँ चुनें।</strong> दोनों फ़ील्डों को एक ही इकाई, या रूपांतरित समतुल्य, उपयोग करना चाहिए, वरना अनुपात गलत होगा।",
          "<strong>पुष्टि करें कि दोनों माप धनात्मक हैं।</strong> शून्य या ऋणात्मक लंबाई का त्रिभुज में कोई अर्थ नहीं, और यह डेटा प्रविष्टि त्रुटि का संकेत है।",
          "<strong>जाँचें कि कर्ण संलग्न भुजा से लंबा है।</strong> अगर ऐसा नहीं है, तो या तो भुजाएँ गलत लेबल की गई हैं या संख्याएँ समकोण त्रिभुज नहीं बना सकतीं।",
          "<strong>गणना करें sec(A) पर क्लिक करें।</strong> टूल [[c/b]] भाग करता है और अनुपात दिखाता है।",
          "<strong>प्राप्त सेकेंट अनुपात पढ़ें।</strong> यह एक इकाईरहित दशमलव है, आमतौर पर चार दशमलव स्थानों के साथ, आगे की गणनाओं में उपयोग के लिए तैयार।",
          "<strong>पुष्टि करें कि परिणाम 1 से बड़ा है।</strong> न्यून संदर्भ कोण वाले वैध, अपभ्रष्ट न हुए समकोण त्रिभुज के लिए, [[\\sec(A) \\gt 1]]; 1 या उससे कम मान का मतलब है कि ऊपर कुछ गलत हुआ।",
          "<strong>जब इनपुट साफ़ करके दूसरी गणना शुरू करना चाहें तो Reset का उपयोग करें।</strong> फ़ील्ड और परिणाम अपनी प्रारंभिक स्थिति में लौट आते हैं।"
        ],
        "closingParagraphs": [
          "कैलकुलेटर को सम्मुख भुजा या कोण इनपुट की ज़रूरत नहीं, क्योंकि मूल सेकेंट अनुपात दो लंबाइयों से पूरी तरह निर्धारित होता है। यह कोण या छूटी भुजाएँ भी नहीं निकालता; उनके लिए, इस गाइड में बाद में दिए गए पुनर्व्यवस्थित सूत्र मैनुअल रास्ता दिखाते हैं।"
        ]
      },
