            "kind": "p",
            "text": "जब संलग्न भुजा और कोण ज्ञात हों तो सेकेंट सूत्र को कर्ण निकालने के लिए पुनर्व्यवस्थित किया जा सकता है। [[\\sec(A)=c/b]] से शुरू करें और दोनों पक्षों को [[b]] से गुणा करें:"
