            "text": "सेकेंट अनुपात और कोण अलग-अलग राशियाँ हैं: एक भुजाओं की इकाईरहित तुलना है, दूसरा डिग्री में मापा जाता है। अगर सेकेंट अनुपात ज्ञात है, तो व्युत्क्रम से कोसाइन निकालें:"
