      "sec-recover": {
        "h2": "Cómo hallar un ángulo a partir de una razón secante",
        "blocks": [
          {
            "kind": "p",
            "text": "La razón secante y el ángulo son magnitudes distintas: una es una comparación sin dimensiones de los lados, la otra se mide en grados. Si se conoce la razón secante, recupera el coseno con el recíproco:"
          },
          {
            "kind": "p",
            "text": "[[\\cos(A)=\\frac{1}{\\sec(A)}]]"
          },
          {
            "kind": "p",
            "text": "Entonces el coseno inverso devuelve el ángulo:"
          },
          {
            "kind": "p",
            "text": "[[[\\boxed{A=\\cos^{-1}\\left(\\frac{1}{\\sec(A)}\\right)}]]]"
          },
          {
            "kind": "p",
            "text": "Dado [[\\sec(A)=1.25]], primero calcula el coseno: [[\\cos(A)=1/1.25=0.8]]. Luego [[A=\\cos^{-1}(0.8)]], lo que da [[\\boxed{A\\approx36.87^\\circ}]]. Este es un cálculo de ángulo separado, no algo que la calculadora de la razón secante realice directamente. Pon la calculadora científica en modo de grados si se espera la respuesta en grados; en modo de radianes la misma entrada devuelve aproximadamente 0.6435, el mismo ángulo en distintas unidades."
          }
        ]
      },
