        "steps": [
          "<strong>Invertir la fórmula y calcular [[b/c]] en lugar de [[c/b]].</strong> Este es el error más común, y devuelve el coseno en lugar de la secante. Con [[c=5]] y [[b=4]], el orden incorrecto da 0.8; el orden correcto da 1.25.",
          "<strong>Confundir la secante con el coseno.</strong> El coseno es el adyacente dividido entre la hipotenusa; la secante es exactamente lo contrario. Si la respuesta sale por debajo de 1, es casi con seguridad el coseno, no la secante.",
          "<strong>Confundir la secante con la cosecante.</strong> Ambas usan la hipotenusa en el numerador, así que parecen similares. La secante divide entre el cateto adyacente [[b]]; la cosecante divide entre el cateto opuesto [[a]]. Comprueba qué cateto da realmente el problema.",
          "<strong>Usar el cateto opuesto en lugar del adyacente.</strong> Dividir [[c/a]] calcula la cosecante. Con [[c=5]] y [[a=3]], eso da 1.6667, una cosecante correcta pero una secante incorrecta.",
          "<strong>Usar en el numerador un lado que no es la hipotenusa.</strong> La secante siempre tiene la hipotenusa arriba. Cateto entre cateto es tangente o cotangente; cateto entre hipotenusa es seno o coseno.",
          "<strong>Confundir los catetos adyacente y opuesto.</strong> Las etiquetas se intercambian cuando el ángulo de referencia cambia de [[A]] a [[B]]. Confirma siempre qué ángulo nombra el problema antes de asignar [[b]].",
          "<strong>Suponer que la secante es un ángulo medido en grados.</strong> Un resultado de 1.25 es una razón, no [[1.25^\\circ]]. Tratarlo como grados introduce sinsentidos en cualquier cálculo posterior.",
          "<strong>Informar la razón con metros o centímetros.</strong> Las unidades se cancelan en la división, así que «1.25 m» es incorrecto. Escribe el número simple y deja las unidades en las medidas de entrada, donde pertenecen.",
          "<strong>Introducir longitudes de lados cero o negativas.</strong> Un triángulo no puede tener un lado cero o negativo, así que estas entradas señalan un error de entrada de datos o una medida faltante, no un caso límite válido.",
          "<strong>Introducir un cateto adyacente más largo que la hipotenusa.</strong> La hipotenusa es siempre el lado más largo. Si [[b \\gt c]], las entradas están intercambiadas o el triángulo es imposible.",
          "<strong>Mezclar unidades de medida.</strong> Una hipotenusa de 5 m con un cateto adyacente de 40 cm da 0.125, un número sin sentido. Convierte primero a una sola unidad: 5 m y 4 m dan el 1.25 correcto.",
          "<strong>Redondear demasiado pronto.</strong> Redondear una división intermedia a dos decimales y luego continuar el cálculo acumula el error. Mantén la precisión completa en cada paso y redondea solo la respuesta final.",
          "<strong>Suponer que la secante debe valer 1 para un triángulo rectángulo.</strong> Ningún triángulo rectángulo tiene una secante de exactamente 1. Espera un valor por encima de 1, y trata el 1 exacto como señal de que las entradas se invirtieron o el triángulo es degenerado.",
          "<strong>Confundir el coseno recíproco con el coseno inverso.</strong> [[1/\\cos(A)]] es la secante, una razón; [[\\cos^{-1}]] es el coseno inverso, que devuelve un ángulo. Los nombres parecidos causan errores reales, así que lee la notación con cuidado.",
          "<strong>Suponer que la secante por sí sola determina las dimensiones absolutas del triángulo.</strong> La secante describe la forma, no el tamaño: infinitos triángulos comparten una secante de 1.25, desde una hipotenusa de 5 cm hasta una de 5 km. La razón fija las proporciones; las longitudes reales necesitan al menos una medida de lado."
        ],
