        "answer": "sec(A) = c / b: divide la hipotenusa c entre el lado adyacente al ángulo A. Con una hipotenusa de 5 cm y un cateto adyacente de 4 cm, el resultado es 5/4 = 1.25. Ese decimal es la respuesta completa, una razón sin dimensiones, no un ángulo."
