            "kind": "p",
            "text": "La sécante est la forme inversée du cosinus : divisez l'hypoténuse par le côté adjacent et vous avez décrit de combien la longueur inclinée dépasse son empreinte horizontale. La formule [[\\sec(A)=c/b]] n'a besoin que de deux mesures, la réponse est toujours un nombre sans dimension supérieur à 1, et elle croît à mesure que l'angle de référence grandit. Lorsqu'un côté manquant est nécessaire, [[c=b\\sec(A)]] retrouve l'hypoténuse ; lorsque l'angle est nécessaire, [[A=\\cos^{-1}(1/\\sec(A))]] le retrouve. Échelle, chevron, rampe ou 3-4-5 de manuel : la méthode ne change jamais : identifiez l'hypoténuse, identifiez le côté adjacent, divisez, et vérifiez avec l'inverse du cosinus."
