      "sec-hypotenuse": {
        "h2": "So finden Sie die Hypotenuse mithilfe des Sekans",
        "blocks": [
          {
            "kind": "p",
            "text": "Die Sekans-Formel lässt sich umstellen, um die Hypotenuse zu finden, wenn Ankathete und Winkel bekannt sind. Beginnen Sie mit [[\\sec(A)=c/b]] und multiplizieren Sie beide Seiten mit [[b]]:"
          },
          {
            "kind": "p",
            "text": "[[[\\boxed{c=b\\sec(A)}]]]"
          },
          {
            "kind": "p",
            "text": "Die Hypotenuse entspricht der Ankathete multipliziert mit dem Sekans des Winkels. Gegeben eine Ankathete von [[b=4\\,\\text{m}]] und ein Winkel von [[A=60^\\circ]], und mit dem Wissen, dass [[\\sec(60^\\circ)=2]]:"
          },
          {
            "kind": "p",
            "text": "[[c=4\\times2]]"
          },
          {
            "kind": "p",
            "text": "[[\\boxed{c=8\\,\\text{m}}]]"
          },
          {
            "kind": "p",
            "text": "Die Hypotenuse ist bei diesem Winkel doppelt so lang wie die Ankathete, was der 30-60-90-Geometrie entspricht: Die Seite gegenüber 30 Grad ist halb so lang wie die Hypotenuse. Die Ankathete lässt sich genauso finden, indem man erneut umstellt:"
          },
          {
            "kind": "p",
            "text": "[[[\\boxed{b=\\frac{c}{\\sec(A)}}]]]"
          },
          {
            "kind": "p",
            "text": "Mit einer Hypotenuse von [[c=10\\,\\text{m}]] und [[A=60^\\circ]]: [[b=10/2]], also [[\\boxed{b=5\\,\\text{m}}]]. Dies sind mathematische Umstellungen derselben Formel. Der Rechner auf dieser Seite gibt das Sekans-Verhältnis aus Seitenlängen zurück; er berechnet keine fehlenden Seiten direkt."
          }
        ]
      },
      "sec-recover": {
        "h2": "So finden Sie einen Winkel aus einem Sekans-Verhältnis",
        "blocks": [
          {
            "kind": "p",
            "text": "Das Sekans-Verhältnis und der Winkel sind verschiedene Größen: Das eine ist ein dimensionsloser Vergleich von Seiten, das andere wird in Grad gemessen. Ist das Sekans-Verhältnis bekannt, gewinnen Sie den Kosinus mit dem Kehrwert zurück:"
          },
          {
            "kind": "p",
            "text": "[[\\cos(A)=\\frac{1}{\\sec(A)}]]"
          },
          {
            "kind": "p",
            "text": "Dann gibt der Arkuskosinus den Winkel zurück:"
          },
          {
            "kind": "p",
            "text": "[[[\\boxed{A=\\cos^{-1}\\left(\\frac{1}{\\sec(A)}\\right)}]]]"
          },
          {
            "kind": "p",
            "text": "Gegeben [[\\sec(A)=1.25]], berechnen Sie zuerst den Kosinus: [[\\cos(A)=1/1.25=0.8]]. Dann [[A=\\cos^{-1}(0.8)]], was [[\\boxed{A\\approx36.87^\\circ}]] ergibt. Dies ist eine separate Winkelberechnung, keine Funktion des Sekans-Verhältnis-Rechners. Stellen Sie den wissenschaftlichen Taschenrechner auf Grad ein, wenn die Antwort in Grad erwartet wird; im Bogenmaß gibt dieselbe Eingabe etwa 0,6435 zurück, denselben Winkel in anderen Einheiten."
          }
        ]
      },
      "sec-mistakes": {
        "h2": "Häufige Fehler bei der Sekans-Berechnung",
        "blocks": [
          {
            "kind": "p",
            "text": "Die meisten Sekans-Fehler stammen von einem umgekehrten Bruch, einer falsch beschrifteten Seite oder einem Einheitenfehler. Gehen Sie diese Liste durch, bevor Sie einem Ergebnis vertrauen."
          }
        ],
        "steps": [
          "<strong>Die Formel umkehren und [[b/c]] statt [[c/b]] berechnen.</strong> Dies ist der häufigste Fehler überhaupt und liefert den Kosinus statt des Sekans. Mit [[c=5]] und [[b=4]] ergibt die falsche Reihenfolge 0,8; die richtige Reihenfolge ergibt 1,25.",
          "<strong>Sekans mit Kosinus verwechseln.</strong> Der Kosinus ist Ankathete geteilt durch Hypotenuse; der Sekans ist das genaue Gegenteil. Kommt die Antwort unter 1 heraus, ist sie fast sicher der Kosinus, nicht der Sekans.",
          "<strong>Sekans mit Kosekans verwechseln.</strong> Beide verwenden die Hypotenuse im Zähler, sehen also ähnlich aus. Der Sekans teilt durch die Ankathete [[b]]; der Kosekans teilt durch die Gegenkathete [[a]]. Prüfen Sie, welche Kathete die Aufgabe tatsächlich angibt.",
          "<strong>Die Gegenkathete statt der Ankathete verwenden.</strong> [[c/a]] zu teilen berechnet den Kosekans. Mit [[c=5]] und [[a=3]] ergibt das 1,6667, einen korrekten Kosekans, aber einen falschen Sekans.",
          "<strong>Eine Seite, die nicht die Hypotenuse ist, im Zähler verwenden.</strong> Der Sekans hat immer die Hypotenuse oben. Kathete über Kathete ist Tangens oder Kotangens; Kathete über Hypotenuse ist Sinus oder Kosinus.",
          "<strong>Ankathete und Gegenkathete verwechseln.</strong> Die Bezeichnungen tauschen sich, wenn der Referenzwinkel von [[A]] zu [[B]] wechselt. Vergewissern Sie sich stets, welchen Winkel die Aufgabe nennt, bevor Sie [[b]] zuweisen.",
          "<strong>Annehmen, der Sekans sei ein Winkel in Grad.</strong> Ein Ergebnis von 1,25 ist ein Verhältnis, nicht [[1.25^\\circ]]. Es als Grad zu behandeln, füttert jede Folgeberechnung mit Unsinn.",
          "<strong>Das Verhältnis mit Metern oder Zentimetern angeben.</strong> Die Einheiten heben sich in der Division auf, „1,25 m\" ist also falsch. Schreiben Sie die reine Zahl und belassen Sie die Einheiten bei den Eingangsmessungen, wo sie hingehören.",
          "<strong>Null oder negative Seitenlängen eingeben.</strong> Ein Dreieck kann keine Seite von null oder negativer Länge haben; solche Eingaben signalisieren einen Dateneingabefehler oder eine fehlende Messung, keinen gültigen Grenzfall.",
          "<strong>Eine Ankathete eingeben, die länger ist als die Hypotenuse.</strong> Die Hypotenuse ist immer die längste Seite. Gilt [[b \\gt c]], sind die Eingaben vertauscht oder das Dreieck unmöglich.",
          "<strong>Maßeinheiten mischen.</strong> Eine Hypotenuse von 5 m mit einer Ankathete von 40 cm ergibt 0,125, eine bedeutungslose Zahl. Rechnen Sie zuerst auf eine einzige Einheit um: 5 m und 4 m ergeben die korrekten 1,25.",
          "<strong>Zu früh runden.</strong> Eine Zwischendivision auf zwei Nachkommastellen zu runden und dann weiterzurechnen, verstärkt den Fehler. Behalten Sie die volle Genauigkeit durch jeden Schritt und runden Sie nur die endgültige Antwort.",
          "<strong>Annehmen, der Sekans müsse für ein rechtwinkliges Dreieck gleich 1 sein.</strong> Kein rechtwinkliges Dreieck hat einen Sekans von genau 1. Erwarten Sie einen Wert über 1 und behandeln Sie exakt 1 als Signal, dass die Eingaben vertauscht waren oder das Dreieck entartet ist.",
          "<strong>Reziproken Kosinus mit Arkuskosinus verwechseln.</strong> [[1/\\cos(A)]] ist der Sekans, ein Verhältnis; [[\\cos^{-1}]] ist der Arkuskosinus, der einen Winkel zurückgibt. Die ähnlichen Namen verursachen echte Fehler, lesen Sie die Schreibweise also sorgfältig.",
          "<strong>Annehmen, der Sekans allein bestimme die absoluten Abmessungen des Dreiecks.</strong> Der Sekans beschreibt Form, nicht Größe: Unendlich viele Dreiecke teilen sich einen Sekans von 1,25, von einer 5-cm-Hypotenuse bis zu einer 5-km-Hypotenuse. Das Verhältnis legt die Proportionen fest; tatsächliche Längen brauchen mindestens eine Seitenmessung."
        ],
        "closingParagraphs": [
          "<strong>Falsch versus richtig: Ein ausgearbeiteter Vergleich</strong>",
          "Gegeben eine Hypotenuse von [[c=5]] und eine Ankathete von [[b=4]]:",
          "<strong>Falsch:</strong> [[4/5=0.8]]. Das ist der Kosinus, nicht der Sekans. Zähler und Nenner sind vertauscht.",
          "<strong>Richtig:</strong> [[\\sec(A)=5/4=1.25]].",
          "<strong>Prüfung:</strong> [[\\cos(A)=0.8]], und [[1/0.8=1.25]]. Die Kehrwertprüfung bestätigt das Ergebnis, und die Antwort liegt über 1, wie jeder gültige Sekans muss."
        ]
      },
