        "answer": "Stellen Sie die Formel zu c = b * sec(A) um. Wenn die Ankathete 4 m beträgt und der Winkel A 60 Grad ist, ist sec(60°) = 2, also c = 4 * 2 = 8 m. Dies ist eine manuelle Umstellung; der Rechner dieser Seite gibt das Verhältnis aus Seitenlängen zurück, keine fehlenden Seiten."
